<?php
require_once '_bootstrap.php';
require_admin_permission('catalog.manage');
require_once __DIR__.'/../offers.php';
$db=admin_db();

function offer_slug(mysqli $db,string $name,int $id=0): string {
    $base=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$name),'-'))?:'offer';$slug=$base;$n=2;
    while(true){$row=$db->execute_query('SELECT id FROM offers WHERE slug=? AND id<>?',[$slug,$id])->fetch_assoc();if(!$row)return $slug;$slug=$base.'-'.$n++;}
}
function replace_offer_packages(mysqli $db,int $offerId,array $ids): void {
    $db->execute_query('DELETE FROM offer_packages WHERE offer_id=?',[$offerId]);
    foreach(array_unique(array_map('intval',$ids)) as $packageId)if($packageId>0)$db->execute_query('INSERT IGNORE INTO offer_packages(offer_id,package_id) VALUES(?,?)',[$offerId,$packageId]);
}

if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$action=$_POST['offer_action']??'save';$id=(int)($_POST['id']??0);
    try{
        if(in_array($action,['activate','pause','archive'],true)){
            $status=$action==='activate'?'active':($action==='pause'?'paused':'archived');$db->execute_query('UPDATE offers SET status=? WHERE id=?',[$status,$id]);admin_audit($db,$action,'offer',(string)$id);redirect_with_message('offers.php','Offer status updated.');
        }
        if($action==='delete'){
            $offer=$db->execute_query('SELECT image,(SELECT COUNT(*) FROM offer_redemptions WHERE offer_id=offers.id) redemptions FROM offers WHERE id=?',[$id])->fetch_assoc();
            if(!$offer)throw new RuntimeException('Offer not found.');if((int)$offer['redemptions']>0)throw new RuntimeException('Offers with redemptions must be archived, not deleted.');
            $db->begin_transaction();$db->execute_query('DELETE FROM offer_packages WHERE offer_id=?',[$id]);$db->execute_query('DELETE FROM offers WHERE id=?',[$id]);$db->commit();admin_remove_unused_image($db,$offer['image']);admin_audit($db,'delete','offer',(string)$id);redirect_with_message('offers.php','Unused offer deleted.');
        }
        if($action==='duplicate'){
            $source=$db->execute_query('SELECT * FROM offers WHERE id=?',[$id])->fetch_assoc();if(!$source)throw new RuntimeException('Offer not found.');
            $name=$source['name'].' Copy';$slug=offer_slug($db,$name);$db->execute_query("INSERT INTO offers(name,slug,public_heading,description,terms,image,discount_type,discount_value,calculation_scope,minimum_travellers,minimum_booking_amount,maximum_discount,booking_start_at,booking_end_at,usage_limit,per_customer_limit,is_automatic,is_featured,priority,status,created_by) SELECT ?,?,public_heading,description,terms,image,discount_type,discount_value,calculation_scope,minimum_travellers,minimum_booking_amount,maximum_discount,booking_start_at,booking_end_at,usage_limit,per_customer_limit,is_automatic,0,priority,'draft',? FROM offers WHERE id=?",[$name,$slug,$_SESSION['admin_id'],$id]);
            $newId=$db->insert_id;$db->execute_query('INSERT INTO offer_packages(offer_id,package_id) SELECT ?,package_id FROM offer_packages WHERE offer_id=?',[$newId,$id]);admin_audit($db,'duplicate','offer',(string)$newId,$name);redirect_with_message('offers.php?edit='.$newId,'Draft copy created.');
        }

        $name=trim($_POST['name']??'');$heading=trim($_POST['public_heading']??'');$description=trim($_POST['description']??'');$terms=trim($_POST['terms']??'');$code=strtoupper(trim($_POST['code']??''))?:null;
        $type=$_POST['discount_type']??'';$value=(float)($_POST['discount_value']??0);$scope=$_POST['calculation_scope']??'';$minimumTravellers=max(1,(int)($_POST['minimum_travellers']??1));$minimumAmount=max(0,(float)($_POST['minimum_booking_amount']??0));$maximumDiscount=($_POST['maximum_discount']??'')===''?null:max(0,(float)$_POST['maximum_discount']);
        $start=str_replace('T',' ',trim($_POST['booking_start_at']??''));$end=str_replace('T',' ',trim($_POST['booking_end_at']??''));$usageLimit=($_POST['usage_limit']??'')===''?null:max(1,(int)$_POST['usage_limit']);$customerLimit=($_POST['per_customer_limit']??'')===''?null:max(1,(int)$_POST['per_customer_limit']);
        $automatic=!empty($_POST['is_automatic'])?1:0;$featured=!empty($_POST['is_featured'])?1:0;$priority=(int)($_POST['priority']??0);$status=$_POST['status']??'draft';$packageIds=$_POST['package_ids']??[];
        if($name===''||$heading===''||$description===''||$value<=0||!in_array($type,['percentage','fixed'],true)||($type==='percentage'&&$value>100)||!in_array($scope,['booking_total','per_traveller'],true)||!in_array($status,['draft','active','paused','archived'],true)||!strtotime($start)||!strtotime($end)||strtotime($end)<=strtotime($start)||!$packageIds)throw new RuntimeException('Complete the offer, select packages, and use a valid date range.');
        if(!$automatic&&!$code)throw new RuntimeException('Coupon-only offers require a coupon code.');
        $old=$id?$db->execute_query('SELECT image FROM offers WHERE id=?',[$id])->fetch_assoc():null;$image=admin_upload_image('offer_image','offers')?:($old['image']??null);$slug=offer_slug($db,$name,$id);
        $params=[$name,$slug,$heading,$description,$terms,$image,$code,$type,$value,$scope,$minimumTravellers,$minimumAmount,$maximumDiscount,$start,$end,$usageLimit,$customerLimit,$automatic,$featured,$priority,$status];
        $db->begin_transaction();
        if($id){$params[]=$id;$db->execute_query('UPDATE offers SET name=?,slug=?,public_heading=?,description=?,terms=?,image=?,code=?,discount_type=?,discount_value=?,calculation_scope=?,minimum_travellers=?,minimum_booking_amount=?,maximum_discount=?,booking_start_at=?,booking_end_at=?,usage_limit=?,per_customer_limit=?,is_automatic=?,is_featured=?,priority=?,status=? WHERE id=?',$params);}
        else{$params[]=$_SESSION['admin_id'];$db->execute_query('INSERT INTO offers(name,slug,public_heading,description,terms,image,code,discount_type,discount_value,calculation_scope,minimum_travellers,minimum_booking_amount,maximum_discount,booking_start_at,booking_end_at,usage_limit,per_customer_limit,is_automatic,is_featured,priority,status,created_by) VALUES('.implode(',',array_fill(0,22,'?')).')',$params);$id=$db->insert_id;}
        replace_offer_packages($db,$id,$packageIds);$db->commit();if($old&&$image!==$old['image'])admin_remove_unused_image($db,$old['image']);admin_audit($db,$old?'update':'create','offer',(string)$id,$name);redirect_with_message('offers.php','Offer saved successfully.');
    }catch(Throwable $error){if($db->errno){try{$db->rollback();}catch(Throwable $ignored){}}redirect_with_message('offers.php'.($id?'?edit='.$id:'?action=new'),$error->getMessage());}
}

$packages=[];$result=$db->query("SELECT id,name,destination,price FROM packages WHERE status<>'archived' ORDER BY name");while($row=$result->fetch_assoc())$packages[]=$row;
$edit=null;$selectedPackages=[];if(!empty($_GET['edit'])){$id=(int)$_GET['edit'];$edit=$db->execute_query('SELECT * FROM offers WHERE id=?',[$id])->fetch_assoc();$r=$db->execute_query('SELECT package_id FROM offer_packages WHERE offer_id=?',[$id]);while($row=$r->fetch_assoc())$selectedPackages[]=(int)$row['package_id'];}
if(!$edit&&!empty($_GET['package_id']))$selectedPackages[]=(int)$_GET['package_id'];$showForm=isset($_GET['action'])||$edit||!empty($_GET['package_id']);
$search=trim($_GET['q']??'');$status=trim($_GET['status']??'');$where=[];$params=[];if($search!==''){$where[]='(o.name LIKE ? OR o.code LIKE ?)';$params[]='%'.$search.'%';$params[]='%'.$search.'%';}if($status!==''){$where[]='o.status=?';$params[]=$status;}$whereSql=$where?' WHERE '.implode(' AND ',$where):'';
$count=$db->execute_query('SELECT COUNT(*) total FROM offers o'.$whereSql,$params)->fetch_assoc()['total']??0;$pages=max(1,(int)ceil($count/10));$page=min(max(1,(int)($_GET['page']??1)),$pages);$offset=($page-1)*10;
$offers=$db->execute_query("SELECT o.*,(SELECT COUNT(*) FROM offer_packages op WHERE op.offer_id=o.id) package_count,(SELECT COUNT(*) FROM offer_redemptions r JOIN bookings b ON b.id=r.booking_id WHERE r.offer_id=o.id AND b.status NOT IN ('cancelled','rejected')) redemptions,(SELECT COALESCE(SUM(r.base_amount),0) FROM offer_redemptions r JOIN bookings b ON b.id=r.booking_id WHERE r.offer_id=o.id AND b.status NOT IN ('cancelled','rejected')) gross_revenue,(SELECT COALESCE(SUM(r.discount_amount),0) FROM offer_redemptions r JOIN bookings b ON b.id=r.booking_id WHERE r.offer_id=o.id AND b.status NOT IN ('cancelled','rejected')) discount_total,(SELECT COALESCE(SUM(r.final_amount),0) FROM offer_redemptions r JOIN bookings b ON b.id=r.booking_id WHERE r.offer_id=o.id AND b.payment_status='paid') net_revenue FROM offers o{$whereSql} ORDER BY o.created_at DESC LIMIT 10 OFFSET {$offset}",$params);
$metrics=$db->query("SELECT SUM(status='active' AND NOW() BETWEEN booking_start_at AND booking_end_at) active_count,SUM(status='active' AND booking_start_at>NOW()) scheduled_count,SUM(status='active' AND booking_end_at BETWEEN NOW() AND DATE_ADD(NOW(),INTERVAL 7 DAY)) expiring_count FROM offers")->fetch_assoc();$money=$db->query("SELECT COUNT(*) redemptions,COALESCE(SUM(CASE WHEN b.status NOT IN ('cancelled','rejected') THEN r.discount_amount ELSE 0 END),0) discounts,COALESCE(SUM(CASE WHEN b.payment_status='paid' THEN r.final_amount ELSE 0 END),0) revenue FROM offer_redemptions r JOIN bookings b ON b.id=r.booking_id")->fetch_assoc();
$pageTitle='Offers';include '_header.php';
?>
<div class="page-head"><div><span>Promotions & pricing</span><h1>Offers</h1><p>Create temporary promotions without changing permanent package prices.</p></div><a class="primary-btn" href="offers.php?action=new"><i class="fa-solid fa-plus"></i>Create offer</a></div>
<div class="metric-grid"><div class="metric"><i class="fa-solid fa-tags"></i><span>Active offers</span><strong><?php echo (int)$metrics['active_count'];?></strong></div><div class="metric"><i class="fa-solid fa-clock"></i><span>Scheduled</span><strong><?php echo (int)$metrics['scheduled_count'];?></strong></div><div class="metric"><i class="fa-solid fa-hourglass-end"></i><span>Expiring soon</span><strong><?php echo (int)$metrics['expiring_count'];?></strong></div><div class="metric"><i class="fa-solid fa-ticket"></i><span>Redemptions</span><strong><?php echo (int)$money['redemptions'];?></strong></div><div class="metric"><i class="fa-solid fa-indian-rupee-sign"></i><span>Revenue after discounts</span><strong><?php echo inr($money['revenue']);?></strong></div></div>
<?php if($showForm):?><section class="panel form-panel"><div class="panel-head"><h2><?php echo $edit?'Edit offer':'Create offer';?></h2><a href="offers.php">Close</a></div><form class="admin-form" method="post" enctype="multipart/form-data"><?php echo csrf_input();?><input type="hidden" name="id" value="<?php echo (int)($edit['id']??0);?>"><input type="hidden" name="offer_action" value="save">
<label>Internal name<input name="name" value="<?php echo e($edit['name']??'');?>" required></label><label>Public heading<input name="public_heading" value="<?php echo e($edit['public_heading']??'');?>" required></label><label class="wide">Short description<textarea name="description" required><?php echo e($edit['description']??'');?></textarea></label><label class="wide">Terms and conditions<textarea name="terms"><?php echo e($edit['terms']??'');?></textarea></label>
<label>Discount type<select name="discount_type"><option value="percentage" <?php echo ($edit['discount_type']??'')==='percentage'?'selected':'';?>>Percentage</option><option value="fixed" <?php echo ($edit['discount_type']??'')==='fixed'?'selected':'';?>>Fixed INR</option></select></label><label>Discount value<input type="number" min="0.01" step="0.01" name="discount_value" value="<?php echo e($edit['discount_value']??'');?>" required></label><label>Calculation scope<select name="calculation_scope"><option value="booking_total" <?php echo ($edit['calculation_scope']??'')==='booking_total'?'selected':'';?>>Booking total</option><option value="per_traveller" <?php echo ($edit['calculation_scope']??'')==='per_traveller'?'selected':'';?>>Per traveller</option></select></label><label>Maximum discount (INR)<input type="number" min="0" step="1" name="maximum_discount" value="<?php echo e($edit['maximum_discount']??'');?>"></label>
<label>Starts<input type="datetime-local" name="booking_start_at" value="<?php echo !empty($edit['booking_start_at'])?e(date('Y-m-d\TH:i',strtotime($edit['booking_start_at']))):'';?>" required></label><label>Ends<input type="datetime-local" name="booking_end_at" value="<?php echo !empty($edit['booking_end_at'])?e(date('Y-m-d\TH:i',strtotime($edit['booking_end_at']))):'';?>" required></label><label>Minimum travellers<input type="number" min="1" name="minimum_travellers" value="<?php echo (int)($edit['minimum_travellers']??1);?>"></label><label>Minimum booking amount<input type="number" min="0" name="minimum_booking_amount" value="<?php echo e($edit['minimum_booking_amount']??0);?>"></label><label>Coupon code <small>Required when automatic application is off</small><input name="code" value="<?php echo e($edit['code']??'');?>"></label><label>Usage limit<input type="number" min="1" name="usage_limit" value="<?php echo e($edit['usage_limit']??'');?>"></label><label>Per-customer limit<input type="number" min="1" name="per_customer_limit" value="<?php echo e($edit['per_customer_limit']??'');?>"></label><label>Priority<input type="number" name="priority" value="<?php echo (int)($edit['priority']??0);?>"></label><label>Status<select name="status"><?php foreach(['draft','active','paused','archived'] as $v):?><option value="<?php echo $v;?>" <?php echo ($edit['status']??'draft')===$v?'selected':'';?>><?php echo ucfirst($v);?></option><?php endforeach;?></select></label><label><span>Publishing options</span><span><input type="checkbox" name="is_automatic" value="1" <?php echo !isset($edit['is_automatic'])||$edit['is_automatic']?'checked':'';?>> Apply automatically</span><span><input type="checkbox" name="is_featured" value="1" <?php echo !empty($edit['is_featured'])?'checked':'';?>> Featured offer</span></label>
<label class="wide upload-field">Promotional image <small>Optional JPG, PNG, or WebP up to 5 MB.</small><?php if(!empty($edit['image'])):?><img class="upload-preview" src="../<?php echo e($edit['image']);?>" alt="Current offer image"><?php endif;?><input type="file" name="offer_image" accept="image/jpeg,image/png,image/webp"></label><div class="offer-packages"><strong>Eligible packages</strong><?php foreach($packages as $package):?><label><input type="checkbox" name="package_ids[]" value="<?php echo (int)$package['id'];?>" <?php echo in_array((int)$package['id'],$selectedPackages,true)?'checked':'';?>><span><?php echo e($package['name']);?><small><?php echo e($package['destination']);?> · <?php echo inr($package['price']);?></small></span></label><?php endforeach;?></div><div class="form-actions"><button><i class="fa-solid fa-floppy-disk"></i>Save offer</button></div></form></section><?php endif;?>
<section class="panel"><div class="panel-head"><h2>Offer register</h2><form class="search-form" method="get"><input name="q" value="<?php echo e($search);?>" placeholder="Search offers or codes"><select name="status"><option value="">All statuses</option><?php foreach(['draft','active','paused','archived'] as $v):?><option <?php echo $status===$v?'selected':'';?>><?php echo ucfirst($v);?></option><?php endforeach;?></select><button class="primary-btn"><i class="fa-solid fa-search"></i>Search</button><a class="reset-btn" href="offers.php"><i class="fa-solid fa-rotate-left"></i>Reset</a></form></div><div class="table-wrap"><table><thead><tr><th>Offer</th><th>Discount</th><th>Packages</th><th>Schedule</th><th>Usage</th><th>Revenue</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php while($offer=$offers->fetch_assoc()):$live=$offer['status']==='active'&&strtotime($offer['booking_start_at'])<=time()&&strtotime($offer['booking_end_at'])>=time();?><tr><td><strong><?php echo e($offer['name']);?></strong><small><?php echo e($offer['code']?:'Automatic offer');?></small></td><td><?php echo e(offer_label($offer));?><small><?php echo e(str_replace('_',' ',$offer['calculation_scope']));?></small></td><td><?php echo (int)$offer['package_count'];?></td><td><?php echo e(date('d M Y',strtotime($offer['booking_start_at'])));?><small>to <?php echo e(date('d M Y',strtotime($offer['booking_end_at'])));?></small></td><td><?php echo (int)$offer['redemptions'];?><?php echo $offer['usage_limit']?' / '.(int)$offer['usage_limit']:'';?></td><td><?php echo inr($offer['net_revenue']);?><small><?php echo inr($offer['discount_total']);?> discounted</small></td><td><span class="pill"><?php echo $live?'live':e($offer['status']);?></span></td><td><div class="action-row"><a class="icon-btn" href="../offers.php?preview=<?php echo (int)$offer['id'];?>" title="Preview"><i class="fa-solid fa-eye"></i></a><a class="icon-btn" href="offers.php?edit=<?php echo (int)$offer['id'];?>" title="Edit"><i class="fa-solid fa-pen"></i></a><form method="post"><?php echo csrf_input();?><input type="hidden" name="id" value="<?php echo (int)$offer['id'];?>"><button class="icon-btn" name="offer_action" value="duplicate" title="Duplicate"><i class="fa-solid fa-copy"></i></button></form><form method="post"><?php echo csrf_input();?><input type="hidden" name="id" value="<?php echo (int)$offer['id'];?>"><button class="icon-btn" name="offer_action" value="<?php echo $offer['status']==='active'?'pause':'activate';?>" title="<?php echo $offer['status']==='active'?'Pause':'Activate';?>"><i class="fa-solid <?php echo $offer['status']==='active'?'fa-pause':'fa-play';?>"></i></button></form><form method="post" onsubmit="return confirm('Delete this unused offer?')"><?php echo csrf_input();?><input type="hidden" name="id" value="<?php echo (int)$offer['id'];?>"><button class="icon-btn danger-icon" name="offer_action" value="delete" title="Delete unused offer"><i class="fa-solid fa-trash"></i></button></form></div></td></tr><?php endwhile;?></tbody></table></div><?php admin_pagination(['pages'=>$pages,'page'=>$page,'parameter'=>'page']);?></section>
